import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).parent))
from corlib import *
E = []
CB_ART = {"sup": ["artery-sca"], "inf": ["artery-pica", "artery-aica"], "all": ["artery-sca", "artery-pica", "artery-aica"]}
CB_TERR = {"sup": ["territory-superior-cerebellar"], "inf": ["territory-inferior-cerebellar"], "all": ["territory-superior-cerebellar", "territory-inferior-cerebellar"]}
def lob(id, name, art, summary, location, function, views, normal, paths, lesion, exam, pearls, cites, **kw):
    kw.setdefault("territories", CB_TERR[art]); kw.setdefault("parent", "cerebellar-hemisphere"); kw.setdefault("subsystem", "lobules")
    kw.setdefault("pathways", ["pathway-cerebellar-circuits"]); kw.setdefault("syndromes", ["syn-cerebellar-hemispheric", "syn-cerebellar-vermian-midline"])
    return cortex(id, name, "x", summary, location, function, CB_ART[art], views, normal, paths, lesion, exam, pearls, cites, system="cerebellum", **kw)
V_ART = ["artery-sca", "artery-pica"]
def vm(id): return [f"{id}-l", f"{id}-r"]

E.append(lob("cerebellar-lobule-i-iv", "Lobules I–IV", "sup",
 "Lobules I to IV form the anterior part of the anterior lobe of the cerebellum, the lingula, central lobule and culmen of the vermis with their small hemispheric wings, tucked under the tentorium in front of the primary fissure and behind the superior medullary velum. They are spinocerebellar cortex receiving the spinocerebellar tracts from the legs and trunk and projecting through the fastigial and interposed nuclei to the vestibulospinal and reticulospinal systems, so they regulate muscle tone, posture and the gait of the lower limbs. Their degeneration in chronic alcoholism produces the classic anterior lobe syndrome of a wide-based ataxic gait with relatively preserved arm coordination, and they are compressed by superior vermian and tentorial masses.",
 "Anterior lobe of the cerebellum from the superior medullary velum back to the primary fissure, rostral and superior to lobule V, mostly vermian with small hemispheric extensions, lying beneath the tentorium and behind the midbrain and the superior cerebellar peduncles.",
 "The anterior lobe cortex receives the dorsal and ventral spinocerebellar tracts (leg and trunk proprioception and copies of spinal interneuron activity) and the cuneocerebellar tract from the arm, together with pontine input from the sensorimotor cortex and olivary climbing fibers; its Purkinje cells inhibit the fastigial and interposed nuclei, which drive the vestibulospinal, reticulospinal and rubrospinal systems and the ventrolateral thalamus. The result is continuous adjustment of limb tone and of the timing of the leg muscles in walking and standing, with a somatotopic map in which the legs are represented anteriorly. Loss produces gait and stance ataxia and hypotonia of the legs.",
 [mview("sagittal", "cerebellar-lobule-i-iv-l", "anterior lobe of the vermis in front of the primary fissure"), mview("coronal", "cerebellar-lobule-i-iv-r", "anterior lobe beneath the tentorium")],
 "The anterosuperior vermis on midline sagittal images between the fourth ventricle roof and the primary fissure, folded into narrow folia; atrophy widens its fissures before the rest of the cerebellum.",
 [pathol("Alcoholic cerebellar degeneration", "MRI", "Selective atrophy of the anterior superior vermis with widened folia on sagittal images, in a patient with gait ataxia and relatively spared limbs.", sequence="T1"),
  pathol("Superior cerebellar artery infarct", "MRI", "Restricted diffusion of the superior cerebellum including the anterior lobe with gait and limb ataxia and, when swollen, brainstem compression.", sequence="DWI"),
  pathol("Superior vermian compression by a tentorial meningioma", "MRI", "Enhancing tentorial mass indenting the anterior lobe with progressive gait ataxia.", sequence="T1+Gd")],
 [("Wide-based, unsteady gait and truncal instability", "bilateral", "Loss of spinocerebellar regulation of leg and trunk muscles"), ("Hypotonia of the legs", "bilateral", "Loss of anterior lobe facilitation of tone through the fastigial and vestibulospinal system"), ("Relatively preserved arm coordination", "n/a", "The arm representation lies in more posterior lobules")],
 ["Tandem gait and Romberg with eyes open (cerebellar patients sway with eyes open)", "Heel-shin test compared with finger-nose test", "Alcohol and nutritional history"],
 ["Anterior lobe atrophy is the cerebellar signature of alcohol: the legs go before the arms", "The anterior vermis on a sagittal MRI is the first place to look for cerebellar atrophy", "Gait ataxia with normal finger-nose testing is anterior lobe, not hemisphere"],
 [R("sp-cerebellum"), R("sp-cerebellar-dysfunction-2"), R("sp-cerebellar-dysfunction")], synonyms=["anterior lobe (rostral part)", "lingula, central lobule and culmen"], mesh_ids=vm("cerebellar-lobule-i-iv"),
 afferents=[("Spinal cord (legs and trunk)", "dorsal and ventral spinocerebellar tracts via the inferior and superior peduncles"), ("Pontine nuclei", "middle cerebellar peduncle"), ("Inferior olive", "climbing fibers via the inferior peduncle")],
 efferents=[("Fastigial and interposed nuclei", "Purkinje axons"), ("Vestibular nuclei (direct)", "juxtarestiform body")]))

E.append(lob("cerebellar-lobule-v", "Lobule V", "sup",
 "Lobule V is the posterior part of the anterior lobe, the culmen of the vermis and its hemispheric extension, ending at the primary fissure that separates the anterior from the posterior lobe. It contains the anterior somatotopic map of the body, with the arm and hand lateral and the leg medial, and it works with the primary motor cortex through the pontine nuclei and the dentate-thalamic projection to time and coordinate limb movements, so its lesions produce limb ataxia and dysmetria of the ipsilateral arm and leg. It is in the superior cerebellar artery territory and it is compressed or infarcted with the rest of the superior cerebellum, and it shows early atrophy in the spinocerebellar ataxias.",
 "Posterior part of the anterior lobe between lobule IV in front and the primary fissure behind, extending from the vermian culmen laterally into the anterior quadrangular lobule of the hemisphere, beneath the tentorium above the superior cerebellar peduncle.",
 "Lobule V receives corticopontine input from the motor and somatosensory cortex through the middle cerebellar peduncle and spinocerebellar input from the limbs, and its Purkinje cells project to the interposed nuclei (intermediate zone) and the dentate nucleus (lateral part), which send the corrected motor signal to the motor cortex through the ventrolateral thalamus and to the red nucleus; this loop predicts the sensory consequences of a movement and corrects it in flight, so that reaching is smooth and rhythmic movements keep time. Climbing fibers from the inferior olive signal errors and drive motor learning. Its lateral part is the cerebellar hand area used in fine finger movements.",
 [mview("sagittal", "cerebellar-lobule-v-l", "lobule V ending at the primary fissure"), mview("coronal", "cerebellar-lobule-v-r", "anterior quadrangular lobule of the hemisphere")],
 "The posterior part of the anterior lobe just in front of the deep primary fissure on sagittal images; on axial images through the superior cerebellum it forms the anterior part of the hemisphere beside the vermis.",
 [pathol("Superior cerebellar artery infarct", "MRI", "Restricted diffusion of the anterior superior cerebellar hemisphere and vermis with ipsilateral limb ataxia and dysarthria.", sequence="DWI"),
  pathol("Spinocerebellar ataxia", "MRI", "Diffuse cerebellar and pontine atrophy with widened fissures, the anterior lobe often affected early; brainstem atrophy distinguishes some subtypes.", sequence="T1"),
  pathol("Cerebellar contusion or hemorrhage", "CT", "Superior cerebellar hematoma from hypertension or trauma with acute ataxia, vomiting and risk of upward herniation.", sequence="CT non-contrast")],
 [("Ipsilateral limb ataxia and dysmetria", "ipsilateral", "Loss of the cerebellar prediction and correction of limb movements"), ("Intention tremor and dysdiadochokinesia", "ipsilateral", "Loss of timing signals through the interposed and dentate nuclei"), ("Hypotonia", "ipsilateral", "Loss of cerebellar facilitation of tone")],
 ["Finger-nose and heel-shin testing on each side", "Rapid alternating movements and rebound", "Handwriting and speech for dysmetria of fine movement"],
 ["Cerebellar signs are ipsilateral because the outflow crosses twice: in the superior cerebellar peduncle and again in the corticospinal tract", "The anterior lobe maps the body twice: once here, once in lobule VIII", "Intention tremor grows as the finger approaches the target; parkinsonian tremor fades"],
 [R("sp-spinocerebellar-dorsal-tract"), R("sp-cerebellar-dysfunction")], synonyms=["culmen (posterior part)", "anterior quadrangular lobule"], mesh_ids=vm("cerebellar-lobule-v"),
 afferents=[("Motor and somatosensory cortex via the pontine nuclei", "middle cerebellar peduncle"), ("Spinal cord", "spinocerebellar tracts"), ("Inferior olive", "climbing fibers")],
 efferents=[("Interposed and dentate nuclei", "Purkinje axons"), ("Motor cortex via the ventrolateral thalamus (from the nuclei)", "superior cerebellar peduncle")]))

E.append(lob("cerebellar-lobule-vi", "Lobule VI", "sup",
 "Lobule VI is the first lobule of the posterior lobe, immediately behind the primary fissure, comprising the declive of the vermis and the posterior quadrangular lobule of the hemisphere, the simplex lobule. It is a transition between the motor cerebellum of the anterior lobe and the cognitive cerebellum of Crus I and II: it holds a second representation of the face, mouth and eye movements, it supports articulation and the timing of speech, and its vermian part with lobule VII is the oculomotor vermis that calibrates saccades. It is a superior cerebellar artery territory, it is involved in the dysarthria of cerebellar strokes, and it is one of the regions most consistently abnormal in the cerebellar cognitive-affective syndrome and in studies of autism.",
 "Anterior part of the posterior lobe between the primary fissure in front and the superior posterior fissure behind, from the vermian declive laterally into the simplex (posterior quadrangular) lobule of the hemisphere, under the tentorium and above the horizontal fissure.",
 "The hemispheric part of lobule VI receives the ventral premotor, motor and somatosensory cortex through the pontine nuclei and the trigeminal system, and its projection through the dentate nucleus to the motor thalamus times the muscles of the mouth, tongue and larynx, so lesions produce scanning dysarthria; the vermian part receives the superior colliculus, the vestibular nuclei and the nucleus prepositus and projects to the fastigial nucleus to adjust saccade amplitude and pursuit gain, so lesions produce saccadic dysmetria and impaired pursuit. Its lateral parts also participate in working memory and language tasks with Crus I, and it is a station of the cerebellar pain and emotional networks.",
 [mview("sagittal", "cerebellar-lobule-vi-l", "lobule VI behind the primary fissure"), mview("axial", "cerebellar-lobule-vi-r", "simplex lobule of the superior hemisphere")],
 "The lobule immediately behind the primary fissure on sagittal images, above the horizontal fissure on the hemisphere; the declive of the vermis is the corresponding midline part.",
 [pathol("Superior cerebellar artery infarct", "MRI", "Restricted diffusion of the superior hemisphere including lobule VI with dysarthria, ipsilateral limb ataxia and nystagmus.", sequence="DWI"),
  pathol("Cerebellar cognitive-affective syndrome", "MRI", "Posterior lobe lesions (stroke, tumor, resection) involving lobule VI and Crus I-II with executive, linguistic and affective change and mild motor signs.", sequence="FLAIR"),
  pathol("Medulloblastoma or pilocytic astrocytoma of the superior vermis", "MRI", "Enhancing midline mass extending into lobule VI with ataxia, vomiting and hydrocephalus in a child.", sequence="T1+Gd")],
 [("Scanning dysarthria", "ipsilateral", "Loss of cerebellar timing of articulatory muscles from the face representation"), ("Saccadic dysmetria and impaired smooth pursuit", "bilateral", "Loss of oculomotor vermis calibration through the fastigial nucleus"), ("Executive and affective change with adjacent Crus I involvement", "n/a", "Disruption of the cerebrocerebellar cognitive loops")],
 ["Repeat syllables and a sentence to detect scanning, explosive speech", "Saccades to targets: overshoot and corrective saccades", "Verbal fluency and affect after a posterior lobe lesion"],
 ["Dysarthria in cerebellar disease is a lobule VI and paravermian sign, usually from the left hemisphere", "The oculomotor vermis (VI-VII) tunes every saccade; its lesion makes the eyes overshoot", "Lobule VI is where the motor cerebellum shades into the cognitive cerebellum"],
 [R("sp-cerebellar-dysfunction"), R("sp-dentate-nucleus")], synonyms=["declive and simplex lobule", "posterior quadrangular lobule"], mesh_ids=vm("cerebellar-lobule-vi"),
 afferents=[("Premotor, motor and prefrontal cortex via the pontine nuclei", "middle cerebellar peduncle"), ("Superior colliculus and vestibular nuclei (vermis)", "tectocerebellar and vestibulocerebellar fibers"), ("Trigeminal nuclei", "trigeminocerebellar fibers")],
 efferents=[("Dentate nucleus (hemisphere) and fastigial nucleus (vermis)", "Purkinje axons"), ("Motor and prefrontal cortex via the thalamus", "superior cerebellar peduncle")]))

E.append(lob("cerebellar-lobule-crus-i", "Crus I", "inf",
 "Crus I is the upper of the two large hemispheric lobules of the posterior lobe (the superior semilunar lobule), lying between lobule VI above the horizontal fissure and Crus II below, forming the bulk of the posterior lateral hemisphere. It is the cognitive cerebellum: it has no somatotopic body map but is connected through the pontine nuclei and the dentate nucleus to the prefrontal, parietal and temporal association cortex, and it participates in working memory, language, executive function and social cognition. Damage causes the cerebellar cognitive-affective syndrome rather than limb ataxia, it is a common site of cerebellar metastases and of PICA-territory infarcts of the posterolateral hemisphere, and its volume is altered in autism and schizophrenia.",
 "Posterior lobe of the hemisphere between the superior posterior fissure and the horizontal fissure, lateral to the vermian folium, forming the superior semilunar lobule that wraps around the lateral edge of the hemisphere below the tentorium.",
 "Crus I receives the dorsolateral prefrontal, posterior parietal and superior temporal cortex through the pontine nuclei and projects via the dentate nucleus and the ventrolateral and mediodorsal thalamus back to the same areas, forming closed loops that apply the cerebellum's predictive, timing and error-correcting computation to thought and language as it does to movement: it supports verbal working memory, planning, set shifting, the fluency of speech and the understanding of other minds. It is a node of the default mode and frontoparietal networks, and its connections with the prefrontal cortex are the anatomical basis of the executive and affective changes after posterior cerebellar lesions.",
 [mview("axial", "cerebellar-lobule-crus-i-l", "Crus I forming the posterolateral hemisphere above the horizontal fissure"), mview("sagittal", "cerebellar-lobule-crus-i-r", "superior semilunar lobule below the tentorium")],
 "The large posterolateral lobule of the cerebellar hemisphere on axial images through the middle of the cerebellum, above the horizontal fissure that separates it from Crus II; its folia run obliquely toward the vermis.",
 [pathol("PICA or SCA border-zone infarct of the posterior hemisphere", "MRI", "Restricted diffusion of the posterolateral hemisphere with mild ataxia and cognitive or affective change out of proportion to motor signs.", sequence="DWI"),
  pathol("Cerebellar metastasis", "MRI", "Ring-enhancing hemispheric lesion with edema in Crus I, presenting with headache, ataxia and hydrocephalus.", sequence="T1+Gd"),
  pathol("Cerebellar cognitive-affective syndrome after resection", "MRI", "Posterolateral hemispheric defect after tumor surgery with executive, language and affect disturbance.", sequence="T1")],
 [("Executive dysfunction and impaired working memory", "n/a", "Disruption of the prefrontal-cerebellar loops through Crus I"), ("Language impairment (agrammatism, reduced fluency) with right hemispheric lesions", "n/a", "Crossed connection of the right cerebellum with the left frontal language cortex"), ("Blunted or disinhibited affect", "n/a", "Disruption of limbic-cerebellar connections")],
 ["Verbal fluency, digit span backward and set-shifting tests after any posterior cerebellar lesion", "Sentence construction and grammar", "Mood and behavior history from the family"],
 ["A cerebellar lesion without ataxia is a Crus I lesion: it changes thinking rather than walking", "The right cerebellum serves the left frontal lobe: right Crus I lesions impair language", "Posterior lobe means cognitive, anterior lobe means motor"],
 [R("sp-cerebellar-dysfunction"), R("sp-dentate-nucleus")], synonyms=["superior semilunar lobule", "Crus I of the ansiform lobule"], mesh_ids=vm("cerebellar-lobule-crus-i"),
 afferents=[("Prefrontal, parietal and temporal association cortex via the pontine nuclei", "middle cerebellar peduncle"), ("Inferior olive (principal olive)", "climbing fibers")],
 efferents=[("Dentate nucleus (ventral, non-motor part)", "Purkinje axons"), ("Prefrontal and parietal cortex via the ventrolateral and mediodorsal thalamus", "superior cerebellar peduncle")]))

E.append(lob("cerebellar-lobule-crus-ii", "Crus II", "inf",
 "Crus II is the lower of the two large posterior hemispheric lobules (the inferior semilunar lobule), between the horizontal fissure above and lobule VIIB below, on the posteroinferior surface of the cerebellum in the posterior inferior cerebellar artery territory. With Crus I it forms the non-motor cerebellum linked to the prefrontal and parietal association cortex, contributing to executive function, language and social cognition, with the tuber of the vermis as its midline part. It is the region most often involved in cerebellar cognitive-affective syndrome after PICA infarcts and tumor resection, and it swells against the medulla and the fourth ventricle in large infarcts, so its edema is a cause of the delayed deterioration that follows cerebellar stroke.",
 "Posterior lobe of the hemisphere below the horizontal fissure and above the ansoparamedian fissure that separates it from lobule VIIB, lateral to the vermian tuber, on the posteroinferior surface of the hemisphere against the occipital bone.",
 "Crus II receives the same prefrontal and parietal association areas as Crus I through the pontine nuclei and returns its output through the dentate nucleus and the thalamus, participating in verbal working memory, planning, the timing of language and the processing of social and emotional information; it is part of the default mode representation in the cerebellum, and its right side is linked to the left language cortex. It contains no body map, so even large lesions produce little limb ataxia, but they disturb the fluency and organization of thought and behavior, and in children posterior lobe resection produces cerebellar mutism when the dentate outflow is also involved.",
 [mview("axial", "cerebellar-lobule-crus-ii-l", "Crus II below the horizontal fissure"), mview("sagittal", "cerebellar-lobule-crus-ii-r", "inferior semilunar lobule on the posteroinferior surface")],
 "The posteroinferior hemispheric lobule below the horizontal fissure on axial images through the lower cerebellum, wrapping toward the vermian tuber; the PICA branches run over its surface.",
 [pathol("PICA territory infarct", "MRI", "Restricted diffusion of the posteroinferior hemisphere including Crus II and lobule VIIB, with vertigo, ataxia and risk of swelling at 2-4 days.", sequence="DWI", timing="Maximal edema at days 2-4; watch the fourth ventricle"),
  pathol("Cerebellar mutism after posterior fossa surgery", "MRI", "Postoperative defect of the posterior hemispheres and vermis with dentate or superior peduncle injury in a child who stops speaking one to two days after surgery.", sequence="T1"),
  pathol("Cerebellar hemorrhage", "CT", "Hemispheric hematoma in the posteroinferior cerebellum with headache, vomiting and ataxia; more than 3 cm or fourth ventricular compression needs surgery.", sequence="CT non-contrast")],
 [("Cerebellar cognitive-affective syndrome", "n/a", "Disruption of the cerebrocerebellar association loops"), ("Little or no limb ataxia", "n/a", "Absence of a somatotopic body map in Crus II"), ("Delayed brainstem compression from swelling after infarction", "bilateral", "Mass effect of the swollen posteroinferior hemisphere on the fourth ventricle and medulla")],
 ["Cognitive screening after a PICA stroke, not only gait testing", "Serial level of consciousness and gaze for 72 hours after a large cerebellar infarct", "Speech output in children after posterior fossa surgery"],
 ["A large Crus II infarct may walk normally and think badly", "Cerebellar stroke deteriorates late: the swelling peaks on the third day", "Posterior fossa mutism appears after a silent interval and is a dentate-outflow injury"],
 [R("sp-cerebellar-dysfunction"), R("sp-cerebellar-infarction")], synonyms=["inferior semilunar lobule", "Crus II of the ansiform lobule"], mesh_ids=vm("cerebellar-lobule-crus-ii"), syndromes=["syn-cerebellar-hemispheric", "syn-pica-cerebellar-infarct"],
 afferents=[("Prefrontal and parietal association cortex via the pontine nuclei", "middle cerebellar peduncle"), ("Inferior olive", "climbing fibers")],
 efferents=[("Dentate nucleus", "Purkinje axons"), ("Prefrontal and parietal cortex via the thalamus", "superior cerebellar peduncle")]))

E.append(lob("cerebellar-lobule-viib", "Lobule VIIB", "inf",
 "Lobule VIIB is the narrow hemispheric lobule between Crus II above and lobule VIIIA below, the gracile lobule, on the inferior surface of the posterior cerebellum, with the vermian tuber and folium as its midline counterparts. It lies at the boundary between the cognitive cerebellum of the ansiform lobules and the second sensorimotor map of lobule VIII, and it contributes to both: its lateral part joins the prefrontal loops for working memory and its medial part receives spinal and pontine sensorimotor input. It is supplied by the posterior inferior cerebellar artery, is involved in PICA infarcts and in the cerebellar cognitive-affective syndrome, and its vermian part belongs to the oculomotor vermis.",
 "Inferior surface of the posterior lobe between the ansoparamedian fissure (below Crus II) and the prebiventer fissure (above lobule VIIIA), extending from the tuber of the vermis laterally as the gracile lobule to the lateral margin of the hemisphere.",
 "Lobule VIIB receives corticopontine fibers from the prefrontal and parietal cortex laterally and from the sensorimotor cortex medially, and spinocerebellar input to its paravermian part, projecting to the dentate and interposed nuclei; functionally it takes part in verbal and spatial working memory and in the planning of sequential movements, and the vermian folium and tuber (VIIA) with lobule VI form the oculomotor vermis that calibrates saccades through the fastigial nucleus. It is one of the lobules in which the cerebellum's contribution to attention and to the timing of cognitive operations has been mapped, and its involvement in posterior lobe lesions adds executive symptoms to gait and ocular signs.",
 [mview("axial", "cerebellar-lobule-viib-l", "lobule VIIB between Crus II and lobule VIIIA"), mview("sagittal", "cerebellar-lobule-viib-r", "gracile lobule on the inferior cerebellar surface")],
 "A narrow lobule on the inferior cerebellar surface on sagittal images below Crus II and above the biventer lobule; the vermian folium and tuber lie at the same level in the midline.",
 [pathol("PICA territory infarct", "MRI", "Restricted diffusion of the inferior posterior hemisphere including lobule VIIB with ataxia, vertigo and subtle executive change.", sequence="DWI"),
  pathol("Cerebellar cognitive-affective syndrome", "FLAIR", "Posterior lobe lesion involving VIIB with Crus I-II producing working memory and executive deficits.", sequence="FLAIR") if False else pathol("Cerebellar cognitive-affective syndrome", "MRI", "Posterior lobe lesion involving VIIB with Crus I-II producing working memory and executive deficits.", sequence="FLAIR"),
  pathol("Oculomotor vermis lesion", "MRI", "Midline lesion of the folium and tuber with saccadic dysmetria and impaired pursuit; medulloblastoma in children, infarct or demyelination in adults.", sequence="T1+Gd")],
 [("Working memory and sequencing deficits", "n/a", "Disruption of the prefrontal loops through lateral VIIB"), ("Saccadic dysmetria (vermian part)", "bilateral", "Loss of oculomotor vermis calibration of saccade amplitude"), ("Mild limb ataxia (medial part)", "ipsilateral", "Involvement of the paravermian sensorimotor representation")],
 ["Digit span and sequencing tasks", "Saccade accuracy to targets", "Finger-nose testing for a paravermian component"],
 ["VIIB is the border lobule: cognition laterally, movement medially, eye movements in the midline", "Saccadic overshoot with a normal brainstem points to the oculomotor vermis", "Posterior lobe strokes deserve a cognitive screen as much as a gait test"],
 [R("sp-cerebellar-dysfunction"), R("sp-dentate-nucleus")], synonyms=["gracile lobule", "lobule VIIB with the vermian tuber"], mesh_ids=vm("cerebellar-lobule-viib"),
 afferents=[("Prefrontal, parietal and sensorimotor cortex via the pontine nuclei", "middle cerebellar peduncle"), ("Spinal cord (paravermian part)", "spinocerebellar tracts"), ("Superior colliculus and vestibular nuclei (vermis)", "tectocerebellar and vestibulocerebellar fibers")],
 efferents=[("Dentate and interposed nuclei; fastigial nucleus (vermis)", "Purkinje axons"), ("Prefrontal and motor cortex via the thalamus", "superior cerebellar peduncle")]))

E.append(lob("cerebellar-lobule-viiia", "Lobule VIIIA", "inf",
 "Lobule VIIIA is the upper part of the biventer lobule on the inferior cerebellar surface, between lobule VIIB above and VIIIB below, with the pyramis of the vermis as its midline part. It contains the second, inverted somatotopic map of the body, so it is a sensorimotor lobule like the anterior lobe: it receives spinocerebellar and corticopontine input from the limbs and trunk and projects through the interposed and dentate nuclei to the motor thalamus and the brainstem. Lesions produce ipsilateral limb ataxia and contribute to the gait disorder of PICA infarcts, its vermian part (the pyramis) participates in trunk and posture control, and it is one of the lobules where the cerebellar contribution to motor learning has been mapped.",
 "Inferior surface of the posterior lobe between the prebiventer fissure above and the intrabiventer fissure below, from the vermian pyramis laterally through the upper biventer lobule to the lateral hemispheric margin, resting on the occipital bone above the cerebellar tonsils.",
 "Lobule VIIIA receives copies of motor commands from the sensorimotor cortex through the pontine nuclei and sensory feedback from the limbs through the spinocerebellar tracts and the lateral reticular nucleus, and its Purkinje cells shape the output of the interposed and dentate nuclei to the motor cortex and the red nucleus, providing a second cerebellar map that is engaged especially in bimanual coordination, rhythmic movements such as tapping and walking, and the learning of new motor sequences. The pyramis receives vestibular and spinal input and controls trunk posture through the fastigial nucleus. Damage adds limb dysmetria and gait ataxia to the vertigo of inferior cerebellar lesions.",
 [mview("axial", "cerebellar-lobule-viiia-l", "lobule VIIIA in the upper biventer lobule"), mview("sagittal", "cerebellar-lobule-viiia-r", "pyramis and biventer region on the inferior surface")],
 "The upper of the two biventer sublobules on the inferior surface of the hemisphere on sagittal and coronal images, lateral to the vermian pyramis and above the tonsil.",
 [pathol("PICA territory infarct", "MRI", "Restricted diffusion of the inferior hemisphere including lobules VIII and the tonsil with limb and gait ataxia and vertigo.", sequence="DWI"),
  pathol("Cerebellar degeneration (paraneoplastic or hereditary)", "MRI", "Diffuse folial atrophy including the inferior hemispheres, progressive ataxia; antibodies and genetics define the cause.", sequence="T1"),
  pathol("Chiari malformation with tonsillar descent", "MRI", "Tonsils below the foramen magnum with crowding of the inferior cerebellum; VIIIA and B are compressed against the occipital bone.", sequence="T1")],
 [("Ipsilateral limb ataxia and dysmetria", "ipsilateral", "Loss of the second sensorimotor map"), ("Gait and trunk ataxia (vermian part)", "bilateral", "Loss of pyramis control of trunk posture through the fastigial nucleus"), ("Impaired rhythmic and bimanual coordination", "ipsilateral", "Loss of timing signals for sequential movements")],
 ["Finger-nose and heel-shin tests", "Rhythmic tapping and bimanual alternating movements", "Tandem gait"],
 ["The cerebellum maps the body twice: lobule VIII is the second, upside-down map", "Rhythm lives in lobule VIII: tapping in time fails with inferior cerebellar lesions", "Inferior cerebellar strokes combine vertigo (nodulus) with ataxia (VIII)"],
 [R("sp-spinocerebellar-dorsal-tract"), R("sp-cerebellar-dysfunction")], synonyms=["biventer lobule (upper part)", "pyramis (vermis)"], mesh_ids=vm("cerebellar-lobule-viiia"),
 afferents=[("Sensorimotor cortex via the pontine nuclei", "middle cerebellar peduncle"), ("Spinal cord and lateral reticular nucleus", "spinocerebellar and reticulocerebellar fibers"), ("Inferior olive", "climbing fibers")],
 efferents=[("Interposed and dentate nuclei; fastigial nucleus (vermis)", "Purkinje axons"), ("Motor cortex and red nucleus via the superior peduncle", "cerebellar outflow")]))

E.append(lob("cerebellar-lobule-viiib", "Lobule VIIIB", "inf",
 "Lobule VIIIB is the lower part of the biventer lobule on the inferior cerebellar surface, between lobule VIIIA above and lobule IX (the tonsil) below, completing the second sensorimotor map of the posterior lobe with a representation of the face and the limbs. It receives spinal, trigeminal and pontine sensorimotor input and projects through the interposed and dentate nuclei, contributing to limb coordination, oral movements and the timing of speech, and its vermian part (pyramis and uvula boundary) supports trunk posture. It is in the posterior inferior cerebellar artery territory and is involved in PICA infarcts and in the tonsillar crowding of Chiari malformation, and it is the lobule adjacent to the tonsils that is compressed in tonsillar herniation.",
 "Lower biventer lobule between the intrabiventer fissure above and the secondary fissure below, lateral to the vermian pyramis-uvula junction, on the inferior surface of the hemisphere immediately above and lateral to the tonsil, against the occipital bone near the foramen magnum.",
 "Lobule VIIIB receives the sensorimotor cortex through the pontine nuclei and proprioceptive input from the limbs and face through the spinocerebellar and trigeminocerebellar pathways, and its Purkinje output through the interposed nuclei adjusts the gain of stretch reflexes and the timing of agonist-antagonist activation in ongoing movement; it participates with VIIIA in rhythmic movement, and with lobule VI in the coordination of the mouth and larynx. Its vermian part contributes vestibulospinal control of stance. Lesions cause ipsilateral limb dysmetria, mild dysarthria and gait instability, and the lobule's proximity to the tonsils means it is deformed early by downward displacement of the cerebellum.",
 [mview("axial", "cerebellar-lobule-viiib-l", "lobule VIIIB above the tonsil"), mview("sagittal", "cerebellar-lobule-viiib-r", "lower biventer lobule near the foramen magnum")],
 "The lowest hemispheric lobule above the tonsil on coronal and sagittal images, immediately lateral to the uvula and pyramis of the vermis.",
 [pathol("PICA territory infarct", "MRI", "Restricted diffusion of the inferior hemisphere and tonsil with limb ataxia, vertigo and risk of tonsillar herniation from swelling.", sequence="DWI"),
  pathol("Chiari I malformation", "MRI", "Tonsillar descent below the foramen magnum with crowding of lobules VIII-IX and a possible syrinx; occipital headache on cough.", sequence="T1"),
  pathol("Tonsillar herniation", "CT", "Obliteration of the cisterna magna with the tonsils and lower biventer lobules pushed into the foramen magnum, compressing the medulla.", sequence="CT non-contrast")],
 [("Ipsilateral limb ataxia", "ipsilateral", "Loss of the lower part of the second sensorimotor map"), ("Mild dysarthria and oral incoordination", "ipsilateral", "Involvement of the face representation"), ("Gait instability", "bilateral", "Vermian pyramis-uvula involvement")],
 ["Limb coordination tests", "Speech articulation", "Cough headache and lower cranial nerve signs when Chiari or herniation is suspected"],
 ["The lowest cerebellar lobules are the first to be crowded when the posterior fossa is small", "A PICA infarct that swells pushes VIIIB and the tonsil into the foramen magnum", "Face and limbs are mapped again here, upside down relative to the anterior lobe"],
 [R("sp-spinocerebellar-dorsal-tract"), R("sp-cerebellar-dysfunction")], synonyms=["biventer lobule (lower part)"], mesh_ids=vm("cerebellar-lobule-viiib"), syndromes=["syn-cerebellar-hemispheric", "syn-tonsillar-herniation", "syn-chiari-tonsillar-ectopia"],
 afferents=[("Sensorimotor cortex via the pontine nuclei", "middle cerebellar peduncle"), ("Spinal cord and trigeminal nuclei", "spinocerebellar and trigeminocerebellar fibers"), ("Inferior olive", "climbing fibers")],
 efferents=[("Interposed and dentate nuclei", "Purkinje axons"), ("Fastigial nucleus (vermian part)", "Purkinje axons")]))

E.append(lob("cerebellar-lobule-ix", "Lobule IX", "inf",
 "Lobule IX is the uvula of the vermis and the cerebellar tonsils of the hemispheres, the most inferior part of the posterior lobe, sitting above the foramen magnum on either side of the medulla. The uvula is vestibulocerebellar cortex with the nodulus, receiving the vestibular nerve and nuclei and controlling vestibulo-ocular and vestibulospinal reflexes and the perception of tilt and self-motion; the tonsils are the parts of the cerebellum that herniate through the foramen magnum in raised intracranial pressure and in Chiari malformation. It is supplied by the posterior inferior cerebellar artery, and its infarction mimics a peripheral vestibular lesion with isolated vertigo.",
 "Inferior vermis (uvula) and the tonsils of the hemispheres between the secondary fissure above and the posterolateral fissure below, above the foramen magnum and the cisterna magna, beside the medulla and behind the fourth ventricle's inferior medullary velum.",
 "The uvula, with the nodulus, receives primary vestibular afferents and vestibular nuclear input together with visual motion signals from the inferior olive and the pontine nuclei, and its Purkinje cells project to the vestibular and fastigial nuclei to calibrate the vestibulo-ocular reflex, to distinguish tilt from translation and to hold gaze after head movements (velocity storage); it also contributes to the control of head and eye movements during locomotion. The tonsils are hemispheric cortex with sensorimotor and cognitive connections through the dentate nucleus, but their clinical importance is mechanical: their descent compresses the medulla and blocks CSF flow. Uvular and nodular damage produces vertigo, downbeat nystagmus and imbalance without limb ataxia.",
 [mview("sagittal", "cerebellar-lobule-ix-l", "uvula of the vermis above the foramen magnum"), mview("coronal", "cerebellar-lobule-ix-r", "cerebellar tonsils beside the medulla")],
 "The tonsils are the rounded inferior lobules on either side of the medulla on coronal images, normally above the foramen magnum by a few millimeters; the uvula is the inferior vermis in front of the cisterna magna on sagittal images.",
 [pathol("Chiari I malformation", "MRI", "Peg-shaped tonsils more than 5 mm below the foramen magnum with effacement of the cisterna magna and, often, a cervical syrinx.", sequence="T1"),
  pathol("Tonsillar herniation", "CT", "Loss of the cisterna magna and tonsils in the foramen magnum from posterior fossa mass or diffuse swelling, with medullary compression and apnea.", sequence="CT non-contrast"),
  pathol("Medial PICA infarct (isolated vertigo)", "MRI", "Restricted diffusion of the uvula, nodulus and tonsil presenting as acute vertigo mimicking vestibular neuritis; head-impulse test normal.", sequence="DWI")],
 [("Vertigo, downbeat nystagmus and imbalance without limb ataxia", "bilateral", "Loss of uvular-nodular calibration of the vestibular nuclei"), ("Impaired vestibulo-ocular reflex adaptation and tilt perception", "bilateral", "Loss of vestibulocerebellar processing"), ("Medullary compression, apnea and death with herniation", "bilateral", "Tonsils driven into the foramen magnum")],
 ["HINTS examination: a normal head impulse with direction-changing or vertical nystagmus is central", "Ability to stand and walk: inferior cerebellar strokes cannot stand", "Cough headache and lower cranial nerve signs for Chiari"],
 ["Isolated vertigo with a normal head-impulse test is a nodulus-uvula stroke until MRI proves otherwise", "Tonsils belong above the foramen magnum; five millimeters below is Chiari", "Never do a lumbar puncture when the tonsils are already in the foramen"],
 [R("sp-cerebellum"), R("sp-vestibular-pathways"), R("sp-tonsillar-herniation")], synonyms=["uvula and tonsils", "vestibulocerebellum (with the nodulus)"], mesh_ids=vm("cerebellar-lobule-ix"), pathways=["pathway-vestibular-vor", "pathway-cerebellar-circuits"], syndromes=["syn-tonsillar-herniation", "syn-chiari-tonsillar-ectopia", "syn-central-vs-peripheral-vertigo", "syn-pica-cerebellar-infarct"],
 afferents=[("Vestibular nerve and nuclei", "juxtarestiform body"), ("Inferior olive (visual motion)", "climbing fibers"), ("Pontine nuclei", "middle cerebellar peduncle")],
 efferents=[("Vestibular nuclei (direct)", "juxtarestiform body"), ("Fastigial nucleus", "Purkinje axons")]))

E.append(lob("cerebellar-lobule-x", "Lobule X (flocculonodular)", "inf",
 "Lobule X is the flocculonodular lobe, the nodulus of the vermis and the flocculi of the hemispheres, the oldest part of the cerebellum and the one most directly tied to the vestibular system. The flocculus, tucked beneath the middle cerebellar peduncle in the cerebellopontine angle, adapts the vestibulo-ocular reflex and holds eccentric gaze and smooth pursuit; the nodulus with the uvula controls the vestibulospinal reflexes and the sense of tilt. Lesions cause gaze-evoked and downbeat nystagmus, impaired pursuit and vertigo with imbalance, and this lobe is damaged in medulloblastoma of the fourth ventricle, in PICA and AICA infarcts, in cerebellopontine angle tumors and in Wernicke encephalopathy.",
 "The nodulus is the most anterior inferior vermian lobule projecting into the fourth ventricle roof below the uvula; each flocculus is a small tufted lobule on the anterior inferior surface of the hemisphere beside the pons and the medulla, under the middle cerebellar peduncle and the vestibulocochlear nerve, joined to the nodulus by the peduncle of the flocculus.",
 "The flocculus receives visual motion signals through the inferior olive and the pontine nuclei and vestibular signals from the nerve and nuclei, and its Purkinje cells project directly to the vestibular nuclei to modify the gain and direction of the vestibulo-ocular reflex during learning, to suppress it during fixation and to stabilize gaze in eccentric positions and during pursuit; the nodulus and uvula process otolith and canal signals to separate tilt from translation, limit the duration of post-rotatory nystagmus, and calibrate the vestibulospinal reflexes for stance. Loss of the flocculus produces gaze-evoked nystagmus, downbeat nystagmus, impaired pursuit and inability to suppress the vestibulo-ocular reflex; loss of the nodulus produces vertigo, periodic alternating nystagmus and truncal ataxia.",
 [mview("axial", "cerebellar-lobule-x-l", "flocculus beneath the middle cerebellar peduncle"), mview("sagittal", "cerebellar-lobule-x-r", "nodulus in the roof of the fourth ventricle")],
 "The flocculus is the small lobule in the cerebellopontine angle cistern below the middle cerebellar peduncle on axial images, easily mistaken for a mass; the nodulus is the anterior inferior vermian lobule projecting into the fourth ventricle on sagittal images.",
 [pathol("Medulloblastoma", "MRI", "Enhancing midline mass arising in the nodulus and fourth ventricle roof in a child, with hydrocephalus, truncal ataxia and vomiting; restricted diffusion because it is densely cellular.", sequence="T1+Gd"),
  pathol("AICA or PICA infarct with flocculus involvement", "MRI", "Restricted diffusion of the flocculus and the adjacent cerebellum with vertigo, gaze-evoked nystagmus and, with AICA, deafness.", sequence="DWI"),
  pathol("Prominent flocculus mimicking a cerebellopontine angle mass", "MRI", "A normally large flocculus protruding into the cistern; follows gray matter on all sequences and does not enhance.", sequence="T2")],
 [("Gaze-evoked and downbeat nystagmus, impaired pursuit", "bilateral", "Loss of flocculus control of gaze holding and the vestibulo-ocular reflex"), ("Vertigo and truncal ataxia with periodic alternating nystagmus", "bilateral", "Loss of nodulus-uvula processing of vestibular signals"), ("Inability to suppress the vestibulo-ocular reflex by fixation", "bilateral", "Loss of the flocculus's visual-vestibular integration")],
 ["Observe nystagmus in primary and eccentric gaze and on downgaze", "Smooth pursuit and VOR suppression (fixate on the thumbs while turning)", "Stance with feet together and eyes open"],
 ["The flocculus is the cerebellum's gaze stabilizer; downbeat nystagmus points to it or to the craniocervical junction", "Medulloblastoma grows from the nodulus, which is why it fills the fourth ventricle", "A big flocculus is a normal finding that has caused unnecessary surgery"],
 [R("sp-vestibulo-ocular-reflex"), R("sp-vestibular-pathways"), R("sp-tonsillar-herniation")], synonyms=["flocculonodular lobe", "archicerebellum", "vestibulocerebellum"], mesh_ids=vm("cerebellar-lobule-x"), parent="flocculonodular-lobe", pathways=["pathway-vestibular-vor", "pathway-cerebellar-circuits"], syndromes=["syn-central-vs-peripheral-vertigo", "syn-cerebellar-vermian-midline", "syn-cerebellopontine-angle", "syn-aica-lateral-pontine"],
 afferents=[("Vestibular nerve and nuclei", "juxtarestiform body"), ("Inferior olive (visual climbing fibers)", "inferior cerebellar peduncle"), ("Pontine nuclei (visual and pursuit signals)", "middle cerebellar peduncle")],
 efferents=[("Vestibular nuclei (direct Purkinje projection)", "juxtarestiform body"), ("Fastigial nucleus (nodulus)", "Purkinje axons")]))

E.append(cortex("cerebellar-white-matter", "Cerebellar white matter", "x",
 "The cerebellar white matter is the branching core of the cerebellum, the arbor vitae, formed by the afferent fibers arriving through the three peduncles and fanning out to the cortex, the Purkinje cell axons converging on the deep nuclei, and the efferent fibers leaving the nuclei. It contains the dentate, interposed and fastigial nuclei and it is continuous with the peduncles at the hilus of the hemisphere. It is the substrate of the cerebellar signs in multiple sclerosis (the middle cerebellar peduncle and hemispheric white matter are favored sites), of leukodystrophies and of the cerebellar edema that follows infarction, and its atrophy accompanies cortical loss in the spinocerebellar ataxias; hemorrhage and tumors here compress the fourth ventricle.",
 "The central white matter of each hemisphere and of the vermis, between the folial cortex and the fourth ventricle, continuous laterally and anteriorly with the inferior, middle and superior cerebellar peduncles, and enclosing the dentate nucleus laterally and the interposed and fastigial nuclei near the midline.",
 "Mossy fibers from the pontine nuclei, the spinal cord, the vestibular system and the reticular nuclei and climbing fibers from the inferior olive travel through the white matter to the granular and molecular layers of the cortex, while Purkinje axons run inward to inhibit the deep nuclei, whose axons leave through the superior peduncle to the red nucleus and thalamus and through the inferior peduncle to the vestibular nuclei and reticular formation; corticonuclear and nucleocortical loops within the white matter regulate the gain of the circuit. The organization is somatotopic along the peduncles and the medullary laminae of each lobule. Its lesions disconnect cortex from nuclei and produce the same ipsilateral ataxia as cortical lesions, with more dysarthria and tremor when the outflow is involved.",
 ["artery-sca", "artery-pica", "artery-aica"],
 [mview("axial", "cerebellar-white-matter-l", "cerebellar white matter around the dentate nucleus"), mview("sagittal", "cerebellar-white-matter-r", "arbor vitae of the cerebellar hemisphere")],
 "The branching bright white matter of the arbor vitae on sagittal T1 images, continuous with the middle cerebellar peduncle; the dentate nucleus appears as a crinkled dark ribbon within it on T2 and susceptibility images.",
 [pathol("Multiple sclerosis", "MRI", "FLAIR-bright lesions of the middle cerebellar peduncle and hemispheric white matter, some enhancing when active, with ataxia, nystagmus and dysarthria.", sequence="FLAIR"),
  pathol("Cerebellar infarct with edema", "MRI", "Restricted diffusion of cortex and white matter followed by swelling that compresses the fourth ventricle at 2-4 days.", sequence="DWI", timing="Swelling peaks on the third day"),
  pathol("Pilocytic astrocytoma", "MRI", "Cystic mass with an enhancing mural nodule in the cerebellar hemisphere of a child, displacing the white matter and the fourth ventricle.", sequence="T1+Gd"),
  pathol("Leukodystrophy or metabolic disease with cerebellar white-matter involvement", "MRI", "Symmetric T2 hyperintensity of the cerebellar white matter and dentate nuclei in metachromatic leukodystrophy, cerebrotendinous xanthomatosis or maple syrup urine disease.", sequence="T2")],
 [("Ipsilateral limb ataxia, dysarthria and tremor", "ipsilateral", "Disconnection of the cortex from the deep nuclei and interruption of the outflow"), ("Nystagmus and gait ataxia", "bilateral", "Interruption of vestibulocerebellar fibers"), ("Fourth ventricular compression and hydrocephalus", "bilateral", "Mass effect from swelling, hemorrhage or tumor in the white matter")],
 ["Limb and gait coordination, speech and eye movements", "Serial consciousness and gaze after a cerebellar infarct", "Metabolic and genetic evaluation when the white-matter change is symmetric"],
 ["Cerebellar white-matter lesions behave like cortical ones but add tremor when they catch the outflow", "Symmetric dentate and white-matter signal change is metabolic until proved otherwise", "The arbor vitae is the map of the peduncles: each branch carries one lobule's fibers"],
 [R("sp-cerebellum"), R("sp-dentate-nucleus")], synonyms=["arbor vitae", "cerebellar medullary center"], system="cerebellum", subsystem="white-matter", parent="cerebellum", territories=["territory-superior-cerebellar", "territory-inferior-cerebellar"], pathways=["pathway-cerebellar-circuits", "pathway-posterior-spinocerebellar", "pathway-anterior-spinocerebellar"], syndromes=["syn-cerebellar-hemispheric", "syn-multiple-sclerosis-pattern", "syn-pica-cerebellar-infarct"],
 afferents=[("Pontine nuclei", "middle cerebellar peduncle (mossy fibers)"), ("Inferior olive", "inferior cerebellar peduncle (climbing fibers)"), ("Spinal cord and vestibular nuclei", "inferior and superior cerebellar peduncles")],
 efferents=[("Red nucleus and thalamus (from the dentate and interposed nuclei)", "superior cerebellar peduncle"), ("Vestibular nuclei and reticular formation (from the fastigial nucleus)", "inferior cerebellar peduncle and juxtarestiform body")],
 pitfalls=["Cerebellar white-matter lesions in multiple sclerosis are often clinically silent; a normal examination does not exclude them"], tags=["arbor vitae", "peduncles", "white matter"]))

write(E)
